  "claims": [
    {
      "claim": "The query shares the diaminopyrimidine/dimethoxyaryl motif with trimethoprim and tetroxoprim; oral trimethoprim produced a mean Cmax of 2.2 mg/L and tetroxoprim 1.7 mg/L after oral dosing, demonstrating measurable systemic exposure for this fragment class, consistent with, though not proof of, F >= 20%.",
      "card_ids": ["C124","C91"]
    },
    {
      "claim": "The query shares the chloroindole/methoxyaryl motif with indomethacin, whose absolute oral bioavailability is 76-80% in humans; L3 indomethacin Cmax values (2.36-2.50 mg/L) confirm oral systemic exposure.",
      "card_ids": ["C07","C14","C108","C127"]
    },
    {
      "claim": "Other methoxy-rich/high-TPSA reference molecules with absolute F values above threshold (alfuzosin 49%, rigosertib 35%, GDC-0810 ~45%, colchicine ~45%, midodrine 93%, 5-HTP 49%) support F >= 20% for this physicochemical space.",
      "card_ids": ["C01","C08","C11","C13","C02","C12","C27","C39"]
    },
    {
      "claim": "No L3 record provides a direct query-relevant F < 20% measurement; low pg/mL Cmax values for flavones/melatonin arise from unrelated scaffolds and low doses and are not transferable as negative evidence.",
      "card_ids": ["C86","C129","C92"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C124","C91","C108","C127","C112","C81"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability measurement or IV-referenced AUC comparison is available.",
    "L3 records provide Cmax/AUC only, not F values; measurable exposure does not by itself establish the F >= 20% threshold.",
    "No query-specific solubility, permeability, first-pass metabolism, or efflux data are available; the low prior is physicochemical only.",
    "Structural transfer from trimethoprim/indomethacin fragments is qualitative; no exact match to the query's benzofuran-diaminopyrimidine-chloroindole scaffold is present.",
    "Some positive records come from modified-release, fed, fasted, or disease-specific populations that may not match the query's unstated condition."
  ],
  "decision_summary": "L3 oral exposure records add measurable Cmax for trimethoprim/tetroxoprim-like and indomethacin-like fragments relevant to the query, but provide no direct F values and no query-relevant sub-20% evidence. The prior high prediction based on L1/L2 gold-context analogs (alfuzosin 49%, indomethacin 76-80%, rigosertib 35%, GDC-0810 ~45%, colchicine ~45%, midodrine 93%, 5-HTP 49%) is retained with moderate confidence."
}

